INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_BUILDING_HELP_BARRACKS','+4 Housing. Requires Masonry and Sanctuary District. Base cost: 100 Production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_BUILDING_HELP_DAWN','900 base Production. Requires Atomic Theory, Atomic Era, twelve confirmed invasion victories, 55 Morale and 150 Provisions. Launch spends 150 Provisions and triggers the Final Night. Defeat it to achieve Humanity Endures and continue Endless Survival.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_BUILDING_HELP_DEPOT','+100 Provisions capacity. Requires Railroad and Sanctuary District. Base cost: 450 Production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_BUILDING_HELP_HOSPITAL','Medical mitigation equivalent to two assigned Physicians. Requires Biology and Sanctuary District. Base cost: 300 Production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_BUILDING_HELP_RESIDENTIAL','+8 Housing. Requires Engineering and Sanctuary District. Base cost: 220 Production.');
