INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_BUILDING_HELP_WATER','+4 Provisions per turn. Requires Chemistry and Sanctuary District. Base cost: 300 Production.');
