INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_CONSPIRACY_1','Expose the conspirators through public testimony: spend supplies, gain 8 Morale and end infiltration.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_CONSPIRACY_2','Offer reconciliation: lose 3 Morale and end infiltration.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_CONSPIRACY_3','Ignore their organization: lose 10 Morale; infiltration persists for ten base turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_DESERTION_1','Care for the garrison: spend supplies and gain 8 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_DESERTION_2','Enforce the oath: lose 5 Morale, gain +20% City Defense for three base turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_DESERTION_3','Allow departures: lose a military unit if more than one remains, and 6 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_DESPERATE_1','Open the gates: spend supplies, gain two Population, one available Farmer and 5 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_DESPERATE_2','Offer directions and aid: gain 2 Morale; survivors remember the gesture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_DESPERATE_3','Refuse sanctuary: lose 10 Morale and add a refusal grievance.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_EXPERT_ACCIDENT_1','Fund an emergency rescue: spend supplies and gain 3 Morale; preserve expertise.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_EXPERT_ACCIDENT_2','Send the medical team: with two medical experts, preserve expertise and lose 2 Morale; otherwise lose the expert and 6 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_EXPERT_ACCIDENT_3','Accept the loss: lose the affected available expert and 6 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_GATES_1','Reinforce the gates: spend 20 base Provisions and 20 base stored Production, repair 60 city damage, gain +20% City Defense for six base turns. Accepted Engineers of Ash halve the supply cost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_GATES_2','Recruit emergency militia: lose one Population and 3 Morale; gain a temporary defender and +20% City Defense for six base turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_GATES_3','Abandon the outer wall: lose 15 Morale, suffer -20% City Defense for six base turns and lose two Housing until repaired (damage capped at four).');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_HERO_1','Honor the rescuer: spend supplies, gain 12 Morale and one available Veteran.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_HERO_2','Record the deed in the Chronicle: gain 6 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_HERO_3','Let the families remember privately: gain 2 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_LAST_HOSPITAL_1','Reequip the clinic: spend supplies, gain one available Physician and 5 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_LAST_HOSPITAL_2','Share the remaining equipment: spend 4 base Provisions and gain 1 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_LAST_HOSPITAL_3','Close the wards: lose one available Physician and 8 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_OUTBREAK_1','Treat the outbreak: spend medical supplies, gain 3 Morale and reduce shortage progression. Physicians lower cost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_OUTBREAK_2','Isolate the affected quarter: lose 4 Morale and 4 base Provisions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_OUTBREAK_3','Let the fever run: lose up to 12 Morale; without three medical experts, lose one Population.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_PROTESTS_1','Hold a public council: spend supplies, gain 10 Morale and reduce the refusal grievance by two.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_PROTESTS_2','Listen to their testimony: gain 2 Morale and reduce the refusal grievance by one.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_PROTESTS_3','Close the square: lose 8 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_REBUILD_1','Fund reconstruction: spend supplies, restore all damaged Housing and gain 7 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_REBUILD_2','Organize volunteer crews: restore one Housing and gain 2 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_REBUILD_3','Leave the ruins: lose 5 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SCIENTIST_1','Fund a search: spend supplies, recover the researcher and an apprentice, gain one available Scientist and 5 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SCIENTIST_2','Let the community search: lose 3 Morale, preserve expertise.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SCIENTIST_3','Abandon the search: lose one available Scientist and 4 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SIEGE_CHILD_1','Share a small feast: spend supplies and gain 12 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SIEGE_CHILD_2','Name the child for the morning: gain 6 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SIEGE_CHILD_3','Keep the moment within the family: gain 2 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SUPPLY_CACHE_1','Equip a recovery expedition: spend 8 base Provisions, recover 40 and gain 5 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SUPPLY_CACHE_2','Retrieve what is close to the entrance: gain 15 base Provisions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_SUPPLY_CACHE_3','Leave it for wandering survivors: gain 3 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_THEFT_1','Restore fair distribution: spend supplies and gain 5 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_THEFT_2','Amnesty in exchange for return: lose 5 base Provisions and gain 2 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_THEFT_3','Leave the theft unanswered: lose 12 base Provisions and 5 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_WATER_FAILURE_1','Rebuild the water main: spend supplies, gain 4 Morale and end the disruption. Accepted Engineers of Ash reduce supply cost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_WATER_FAILURE_2','Use temporary wells: -3 Provisions income for four base turns and -3 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CHOICE_WATER_FAILURE_3','Ration clean water: -3 Provisions income for ten base turns, -8 Morale and an additional medical case.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CITY_RETURNED','An additional city was returned.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CIV','The Last City — Humanity''s Final Refuge');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CIV_PEDIA','When the world fell, one city refused to die. Last Light shelters the remnants of humanity behind walls built from the ruins of vanished kingdoms. Its strength comes from the people it saves, and every new arrival must share its finite supplies. Its chronicles remember every siege and every difficult choice.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_COMPLICATION','Survivor consequence');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CONCEPT_ECONOMY','Provisions, Housing and Morale');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CONCEPT_HELP_ECONOMY','Provisions start at 45 with capacity 200. Base income is 4 per turn, plus 2 from the District, 1 per owned unpillaged Farm/Fishing Boats in the city radius, and 2 per assigned Farmer. Consumption is ceil(ceil(Population*0.6+combat units*0.4)*ration multiplier). Housing starts at 12; the District adds 6. Morale changes Production and local Defense.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CONCEPT_HELP_REFUGEES','Caravans arrive about every 8–14 Standard turns after founding. Accept, quarantine or refuse them. Six separate expertise categories can each assign five survivors; assignments do not use normal specialist slots. Quarantine delays processing and reduces complication risk. Decisions are remembered across saves.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CONCEPT_HELP_SIEGES','The first invasion follows about 24 Standard turns after founding, with later waves about every 16–24 turns. Every fifth is a Major Siege. Failed spawns and timeouts grant no victories. The Harrower strengthens nearby invaders. The Atomic-era Dawn Initiative triggers the Final Night and a narrative achievement after a confirmed victory.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CONCEPT_REFUGEES','Survivors at the Gates');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CONCEPT_SIEGES','The Endless Siege');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CONFIRM','CONFIRM COUNCIL DECISION');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_COST','Cost: {1_Num} Provisions and {2_Num} stored Production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_COUNCIL','SANCTUARY COUNCIL');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISES','Crises');
