INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_CONSPIRACY','A secret faction is promising security without the Council.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_DESERTION','Exhausted defenders are speaking of leaving their posts.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_DESPERATE','Families caught between two raiding armies beg for shelter.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_EXPERT_ACCIDENT','A workshop collapse has trapped a member of the refugee council.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_GATES','The outer gate shudders. There is little time to decide.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_HERO','A defender has rescued families from a burning watchtower.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_LAST_HOSPITAL','The old infirmary has only enough equipment for one more week.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_OUTBREAK','The crowded infirmary reports a spreading fever.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_PROTESTS','Names of refused caravans are being read aloud in the square.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_REBUILD','Families are ready to clear the broken outer residences.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_SCIENTIST','One of the rescued researchers has vanished beyond the lower district.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_SIEGE_CHILD','Above the rumble of siege engines, the infirmary hears a newborn cry.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_SUPPLY_CACHE','Scouts have found sealed stores below an old railway station.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_THEFT','Supplies are disappearing from the protected stores.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_STORY_WATER_FAILURE','The lower wells are fouled and a pressure main has burst.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_SUPPLY_CACHE','Abandoned Supplies');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_THEFT','Food Store Theft');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_WAITING','The Council must resolve a crisis.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CRISIS_WATER_FAILURE','Broken Water Infrastructure');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CULTS','Siege Cults');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DASHBOARD','Population {1_Num} / Housing {2_Num} | Provisions {3_Num} / {4_Num}[NEWLINE]Income +{5_Num} | Consumption -{6_Num} | Net {7_Num} per turn');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN','When the world fell, one city refused to die. Warden, beyond your walls the old world is ash. At your gates stand the exhausted, the wounded and the hopeful. Feed them. Shelter them. Remember them. Let the last light become the first dawn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_AWAITING','The Dawn Initiative is complete but requires restored Morale and supplies.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_AWAITING_SUPPLIES','The Dawn Initiative is built. Restore 55 Morale and 150 Provisions to launch the Final Night.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_ENDURES','HUMANITY ENDURES. The city has survived the Final Night. Endless Survival continues.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_FINAL_ACTIVE','The Final Night is underway. Defeat every tagged attacker to achieve Humanity Endures.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_FINAL_PENDING','The Dawn Initiative has launched. The Final Night is approaching.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_LAUNCHED','The Dawn Initiative launched. 150 Provisions committed; the Final Night approaches.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_LOCKED','The Dawn Initiative: reach Atomic Era, defeat twelve invasions, maintain 55 Morale and gather 150 Provisions, then construct the Initiative.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN_REQUIREMENTS','Requires Atomic Era, twelve invasion victories, 55 Morale and 150 Provisions. The Dawn Initiative costs 900 base Production and consumes 150 Provisions when launched.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DIPLO_ATTACKED','You have brought the long night to our gates. We will meet it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DIPLO_DECLAREWAR','We fight so our people may live to see another morning.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DIPLO_DEFEATED','Remember the people who lived here. Let their light reach someone.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DIPLO_FIRST_GREETING','We shelter those the world has forgotten. Approach our gates in peace.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DIPLO_GREETING_HOSTILE_HELLO','Our walls remember the footsteps of our enemies.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DIPLO_GREETING_NEUTRAL_HELLO','The watch fires still burn. What do you seek?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DIPLO_GREETING_POLITE_HELLO','Your friendship brings warmth to a difficult night.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DISTRICT','Sanctuary District');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DISTRICT_HELP','Replaces Granary and retains all Granary effects. Adds +6 Housing and +2 Provisions per turn. Enables quarantine and Sanctuary infrastructure.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DISTRICT_PEDIA','A Granary became a shelter, a shelter became a neighborhood, and a neighborhood became the beating heart of Last Light. Here caravans are counted, supplies are shared and survivors rebuild their lives.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DISTRICT_REQUIRED','Construct the Sanctuary District first.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DISTRICT_STRATEGY','The foundation of refugee processing, housing and further survival infrastructure.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DUMMY','Sanctuary Council Effects');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_EMERGENCY','Emergency');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_ENEMY_RETREAT','The invasion withdrew or could not be confirmed defeated. No siege legacy was awarded.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_ENGINEERS','Engineers');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_EVENT_EXPIRED','This event has already been resolved or has expired.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_EXPERTS','Experts');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_EXPERTS_HELP','Available experts are survivors, separate from normal city specialists. Assign up to five in each category. Unassigned survivors remain available. Losses remove available experts and reduce assignments when necessary.');
