INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_FINAL_NIGHT','THE FINAL NIGHT — Humanity faces its greatest siege.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_FOUNDED','Last Light founded — the final sanctuary begins.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_FOUND_FIRST','Found Last Light to establish the Sanctuary Council.');
