INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_PROMO_HELP_BOSS','+25% Combat Strength, +35% City Attack; nearby tagged invasion troops receive +10% Combat Strength.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_PROMO_HELP_COMMAND','+10% Combat Strength within two plots of the living wave commander; refreshed on turns.');
