INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_PROMO_HELP_VETERAN_2','Persistent record of 2 Major Sieges survived near Last Light. Grants +6% Defense locally through an active promotion.');
