INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RATION_CHANGED','Ration policy changed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RATION_HELP','Select a policy to preview its effects, then confirm. Cooldown remaining: {1_Num} turns. Growth adjusts stored Food by a fraction of positive native surplus; shortages add a further penalty.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RATION_PREVIEW','{1_Name}: Consumption {2_Num}, Net {3_Num}[NEWLINE]Morale {4_Num}/turn | Surplus growth adjustment {5_Num}%');
