INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REAVERS','Iron Reavers');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REFUGEES','Refugees');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REFUGEES_WAITING','A refugee caravan waits at the gates.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REFUGEE_ACCEPT','Accept: +{1_Num} Population, +1 available {2_Name}, pay {3_Num} Provisions. Full risk unless already quarantined.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REFUGEE_QUARANTINE','Quarantine: pay {3_Num} Provisions now, delay processing, and reduce infectious risk. The remaining cost is due on acceptance.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REFUGEE_REFUSE','Refuse: no Population or expertise. Preserve supplies and lose 10 Morale. Earlier refusals can fuel later unrest.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REFUSE','Refuse');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REFUSED','Refugees refused.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_REMNANTS','The Remnants');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RETURN_BLOCKED','A gifted city has no living recipient. It remains an exceptional puppet; see engine limitations.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_BRILLIANT','Possible benefit: an extra available Scientist.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_COMMANDER','Possible benefit: an extra available Veteran and +6 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_DISEASE','Risk: infectious illness may consume medical supplies, damage Morale and cost Population; Physicians and quarantine mitigate it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_INFILTRATION','Risk: enemy infiltration costs supplies and Morale, and increases later unrest pressure.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_LEADERSHIP','Possible benefit: skilled leadership adds 10 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_MEDICAL','Possible benefit: an extra available Physician and +4 Morale.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_OVERCROWDING','Risk: housing tensions (-5 Morale), in addition to normal overcrowding penalties.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_SMUGGLING','Possible consequence: hidden supplies (+8 base Provisions) and distrust (-3 Morale).');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_SUPPLIES','Possible benefit: the caravan carries 20 base Provisions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_THEFT','Risk: hungry survivors steal 10 base Provisions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_RISK_UNREST','Risk: political unrest. Earlier refusals make the consequences worse.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SAVE_UNSUPPORTED','Last City save unavailable — see Lua log.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SCAVENGERS','Starving Scavengers');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SCHOLARS','Scholars');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SCIENTISTS','Scientists');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SELECT','Preview');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SELECT_HELP','Select an available decision to review its effects before confirming.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SHORT','The Last City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SIEGE_VICTORY','The invasion was defeated. Last Light endures.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SKILL_ENGINEERS','+3% Production per assigned Engineer; maximum +15%.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SKILL_FARMERS','+2 Provisions per turn per assigned Farmer; maximum +10.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SKILL_PHYSICIANS','Each assigned Physician reduces caravan disease risk, shortage mortality risk and outbreak treatment cost/severity. Maximum five.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SKILL_SCHOLARS','+3% Culture per assigned Scholar, and +0.08 Morale recovery per turn under safe, adequately supplied conditions; maximum five.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SKILL_SCIENTISTS','+3% Science per assigned Scientist; maximum +15%.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SKILL_VETERANS','+2% Defense per assigned Veteran to combat units within three plots of Last Light; maximum +10%.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SOLDIER_LOST','A defender fell.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPAWN_BLOCKED','The approach is blocked. The invasion has been postponed; no survival reward was granted.');
