INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STABLE','Stable');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STANDARD','Standard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STARVATION_DEATH','Population lost to sustained shortages.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STATUS','Provisions {1_Num} | Morale {2_Num}');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_ARCHIVE','Teachers have memorized the books they could not carry. They offer stories, laws and a stubborn faith in civilization.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_ASH','A caravan has escaped the machinery halls of a fallen industrial settlement. Its engineers bring blueprints and the memory of strong gates.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_BROKEN_BANNER','Soldiers of a defeated garrison arrive with empty quivers. Their commander still knows how to hold a wall.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_CROWDED','Students and researchers arrive with their families. Their science is valuable; their numbers strain the shelters.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_EXILES','Scholars driven from a ruined republic debate at the gates. They will remember how the Warden treats the powerless.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_FEVER','An exhausted medical caravan approaches. Several children are feverish, and its physicians have used their last medicine.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_HUNGRY','A farming village has lost its last crop. Hunger has taught its survivors to take what they need.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_MERCY','A travelling clinic has crossed the wasteland. Its physicians ask for clean water and a place to lay their wounded.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_OBSERVATORY','Astronomers carry rescued instruments under dust-stained blankets. One claims to have solved a problem the old world never could.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_SEED','Farmers have carried sealed jars through winter and ruin. Their seeds and knowledge could feed another generation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_SILENT','A small patrol refuses to name its former commander. Its veterans may be protectors, or the eyes of an approaching army.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STORY_SMUGGLERS','Mechanics pull carts covered in false bottoms. Their hidden cargo could replenish the stores, but trust is fragile.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STRATEGY','Build the Sanctuary District, supply improvements and a defensive garrison early. Assign Farmers before population outruns Provisions; build housing before accepting large caravans. Preserve Last Watch survivors during Major Sieges to develop their veteran legacy. Prepare for the Dawn Initiative after twelve victories in the Atomic Era.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STRICT','Strict');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SUPPLIES_REQUIRED','Requires {1_Num} Provisions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_TECH_REQUIRED','Research the required technology first.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_THREAT','Estimated force: up to {1_Num} units. Assault in {2_Num} turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_TRAIT','The Final Sanctuary');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_TRAIT_HELP','One permanent city. Cannot found more cities or capture enemy cities after founding Last Light. Defenders within three plots of the capital gain +15% Defense. Every fifth invasion is a Major Siege; each defeated Major Siege grants +2% City Defense, up to +30%. Refugees, Provisions, Housing, Morale and rationing are managed in the Sanctuary Council.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_UNAVAILABLE','This action is currently unavailable.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_UNITED','United (+10% Production, +5% local Defense)');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_UNREST','Unrest (-15% Production)');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_VETERANS','Veterans');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_WARNING','An invasion approaches. Prepare the walls.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_WATCH','Last Watch');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_WATCH_HELP','Replaces Spearman and retains its normal abilities. Shares the civilization''s +15% local Defense bonus, without a duplicate bonus. Surviving Major Sieges while present within three plots of Last Light grants +3% local Defense per siege, up to +15%. Last Watch identity and veteran ranks persist through upgrades.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_WATCH_PEDIA','Their oaths are carved into the stones of the gate. The Last Watch stands between the city and the long night. Experienced survivors carry their knowledge into every later generation of defenders.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_WATCH_STRATEGY','Keep these defenders near Last Light during Major Sieges, and upgrade survivors to retain veteran ranks.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_WAVE_ACTIVE','Wave {1_Num}: {2_Num} invaders remain');
